// REV-07: An expired insurance certificate cannot be approved.
//
// Assumptions to verify against the running API:
// - The expiry date is read from the uploaded insurance certificate during extraction.
//   The file below states a "yesterday" expiration date. If the extractor reads a
//   different field, adjust `buildCertificate`.
// - Documents reach status "extracted" within the polling window.
//
// Conflict to review: the scenario's note asks that only "status < 500" be asserted
// because the expiry check is flaky in CI. This file instead asserts the exact 409 and
// "insurance_expired" the scenario specifies, since weakening assertions is not allowed.
// If the flakiness is real, relax the assertions with an explicit decision from the owner.
import { expect, expectStatus, test } from "../../fixtures";

const TAG = "@REV-07";
const DAY_MS = 24 * 60 * 60 * 1000;

function isoDate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

function buildCertificate(expiresOn: string): Buffer {
  return Buffer.from(
    `ACORD CERTIFICATE OF INSURANCE\nPolicy Expiration Date: ${expiresOn}\n`,
    "utf-8",
  );
}

async function waitForAllExtracted(
  member: import("../../fixtures").APIRequestContext,
  vendorId: string,
  expected: number,
): Promise<{ id: string; kind: string }[]> {
  for (let attempt = 0; attempt < 60; attempt++) {
    const response = await member.get(`/api/vendors/${vendorId}/documents`);
    const docs = await expectStatus<{ id: string; kind: string; status: string }[]>(response, 200);
    if (docs.length === expected && docs.every((d) => d.status === "extracted")) {
      return docs;
    }
    if (docs.some((d) => d.status === "failed")) {
      throw new Error("A document failed extraction before the scenario could run.");
    }
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
  throw new Error("Documents were not extracted within the polling window.");
}

test.describe("review vendors", () => {
  test(
    "an expired insurance certificate cannot be approved",
    { tag: TAG },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads all three documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const uniqueSuffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const vendor = await expectStatus<{ id: string }>(
        await member.post("/api/vendors", {
          data: {
            name: `REV-07 Vendor ${uniqueSuffix}`,
            category: "services",
            contact_email: `rev07.${uniqueSuffix}@vendor.test`,
          },
        }),
        201,
      );

      const expiredYesterday = isoDate(new Date(Date.now() - DAY_MS));
      const uploads: { kind: string; name: string; buffer: Buffer }[] = [
        { kind: "insurance_certificate", name: `cert-${uniqueSuffix}.pdf`, buffer: buildCertificate(expiredYesterday) },
        { kind: "w9", name: `w9-${uniqueSuffix}.pdf`, buffer: Buffer.from("W-9 form\n", "utf-8") },
        { kind: "contract", name: `contract-${uniqueSuffix}.pdf`, buffer: Buffer.from("Services contract\n", "utf-8") },
      ];

      for (const upload of uploads) {
        await expectStatus(
          await member.post(`/api/vendors/${vendor.id}/documents`, {
            multipart: {
              kind: upload.kind,
              file: { name: upload.name, mimeType: "application/pdf", buffer: upload.buffer },
            },
          }),
          201,
        );
      }

      // Wait for extraction, then submit so the vendor enters review.
      const docs = await waitForAllExtracted(member, vendor.id, 3);
      const certificate = docs.find((d) => d.kind === "insurance_certificate");
      expect(certificate, "insurance certificate document").toBeDefined();

      const submitted = await expectStatus<{ status: string }>(
        await member.post(`/api/vendors/${vendor.id}/submit`),
        200,
      );
      expect(submitted.status).toBe("in_review");

      const extraction = await expectStatus<{ id: string }>(
        await member.get(`/api/documents/${certificate!.id}/extraction`),
        200,
      );

      // Act: the reviewer tries to approve the expired certificate's extraction.
      const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert
      const body = await expectStatus<{ error: { code: string } }>(response, 409);
      expect(body.error.code).toBe("insurance_expired");
    },
  );
});
